const { listToolsForUser, clearToolListCache } = await import("./runner.js");

let run = 0;
const user = (name: string) => `${name}-${run}`;

describe("listToolsForUser shared tool-list cache", () => {
  beforeEach(() => {
    run += 1;
    clearToolListCache();
    state.spawns = 0;
    state.listCalls = 0;
    state.tools = [{ name: "t1", description: "d", inputSchema: { type: "object" } }];
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("serves every user from one listing for a shared-list server", async () => {
    const results = [];
    for (const name of ["u1", "u2", "u3"]) {
      results.push(await listToolsForUser(user(name), "heisenberg", "Heisenberg", {}));
    }
    expect(state.spawns).toBe(1);
    expect(state.listCalls).toBe(1);
    for (const r of results) expect(r.tools.map((t) => t.name)).toEqual(["t1"]);
  });

  it("does not spawn a per-agent app-tools server just to list tools", async () => {
    await listToolsForUser(user("u1"), "xyne-spaces-app-tools", "App Tools", {}, "agent-a");
    await listToolsForUser(user("u1"), "xyne-spaces-app-tools", "App Tools", {}, "agent-b");
    await listToolsForUser(user("u2"), "xyne-spaces-app-tools", "App Tools", {}, "agent-c");
    expect(state.spawns).toBe(1);
  });

  it("coalesces concurrent first listings onto one spawn", async () => {
    await Promise.all(
      ["u1", "u2", "u3", "u4"].map((name) => listToolsForUser(user(name), "research-agent-mcp", "Research", {})),
    );
    expect(state.spawns).toBe(1);
    expect(state.listCalls).toBe(1);
  });

  it("keeps per-user listing for servers outside the shared set", async () => {
    await listToolsForUser(user("u1"), "bitbucket", "Bitbucket", {});
    await listToolsForUser(user("u2"), "bitbucket", "Bitbucket", {});
    expect(state.spawns).toBe(2);
  });

  it("bypasses the cache when fresh is requested", async () => {
    await listToolsForUser(user("u1"), "heisenberg", "Heisenberg", {});
    await listToolsForUser(user("u2"), "heisenberg", "Heisenberg", {}, undefined, { fresh: true });
    expect(state.spawns).toBe(2);
    expect(state.listCalls).toBe(2);
  });

  it("does not cache an empty listing", async () => {
    state.tools = [];
    await listToolsForUser(user("u1"), "heisenberg", "Heisenberg", {});
    state.tools = [{ name: "t2", description: "", inputSchema: {} }];
    const second = await listToolsForUser(user("u2"), "heisenberg", "Heisenberg", {});
    expect(second.tools.map((t) => t.name)).toEqual(["t2"]);
    expect(state.listCalls).toBe(2);
  });

  it("refreshes the listing after the TTL", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-09-25T00:00:00Z"));
    await listToolsForUser(user("u1"), "heisenberg", "Heisenberg", {});
    vi.setSystemTime(new Date("2026-09-25T00:09:00Z"));
    await listToolsForUser(user("u1"), "heisenberg", "Heisenberg", {});
    expect(state.listCalls).toBe(1);
    vi.setSystemTime(new Date("2026-09-25T00:11:00Z"));
    await listToolsForUser(user("u1"), "heisenberg", "Heisenberg", {});
    expect(state.listCalls).toBe(2);
  });
});

import { describe, expect, it } from "vitest";
import { validateAgentModelConfig } from "./agent-config-validation.js";

describe("validateAgentModelConfig — modelSettings.speed", () => {
  it("accepts fast / standard", () => {
    expect(validateAgentModelConfig({ modelSettings: { speed: "fast" } })).toEqual({ ok: true });
    expect(validateAgentModelConfig({ modelSettings: { speed: "standard" } })).toEqual({ ok: true });
  });

  it("rejects anything else", () => {
    expect(validateAgentModelConfig({ modelSettings: { speed: "turbo" } }).error).toMatch(/modelSettings\.speed must be one of: standard, fast/);
    expect(validateAgentModelConfig({ modelSettings: { speed: true } }).ok).toBe(false);
  });

  it("still rejects unknown modelSettings keys", () => {
    expect(validateAgentModelConfig({ modelSettings: { fastMode: true } }).error).toMatch(/not a recognized setting/);
  });
});

describe("validateAgentModelConfig — fastModeProfile", () => {
  it("accepts inherit and a custom profile", () => {
    expect(validateAgentModelConfig({ fastModeProfile: { providers: "inherit" } })).toEqual({ ok: true });
    expect(validateAgentModelConfig({ fastModeProfile: { providers: "custom", providerOrder: ["claude", "spaces"], models: { claude: "claude-opus-5" } } })).toEqual({ ok: true });
  });
  it("rejects bad shapes", () => {
    expect(validateAgentModelConfig({ fastModeProfile: { providers: "turbo" } }).ok).toBe(false);
    expect(validateAgentModelConfig({ fastModeProfile: { providers: "custom", providerOrder: ["gemini"] } }).ok).toBe(false);
    expect(validateAgentModelConfig({ fastModeProfile: { models: { claude: "" } } }).ok).toBe(false);
    expect(validateAgentModelConfig({ fastModeProfile: { extra: 1 } }).ok).toBe(false);
  });
});

describe("validateAgentModelConfig — fastModeProfile.modelSettings", () => {
  it("accepts run-setting overrides", () => {
    expect(validateAgentModelConfig({ fastModeProfile: { modelSettings: { thinkingLevel: "high", model: "glm-latest", maxTokens: 32000 } } })).toEqual({ ok: true });
  });
  it("rejects bad fields and a nested speed", () => {
    expect(validateAgentModelConfig({ fastModeProfile: { modelSettings: { thinkingLevel: "ultra" } } }).ok).toBe(false);
    expect(validateAgentModelConfig({ fastModeProfile: { modelSettings: { speed: "fast" } } }).error).toMatch(/speed is not allowed/);
    expect(validateAgentModelConfig({ fastModeProfile: { modelSettings: { temperature: 2 } } }).ok).toBe(false);
  });
});

import { describe, expect, it } from "vitest";
import { validateAwakeningConfig } from "./agent-config-validation.js";

const ok = (awakening: unknown) => validateAwakeningConfig({ awakening });

describe("validateAwakeningConfig — accepts", () => {
  it("an absent or empty block", () => {
    expect(validateAwakeningConfig(undefined)).toEqual({ ok: true });
    expect(validateAwakeningConfig({})).toEqual({ ok: true });
    expect(ok(null)).toEqual({ ok: true });
    expect(ok({})).toEqual({ ok: true });
  });

  it("a fully specified valid block", () => {
    expect(
      ok({
        enabled: true,
        kind: "both",
        shadow: false,
        writePolicy: "act",
        periodMs: 1_800_000,
        workspaceId: "ws_1",
        channels: { include: ["ch_1"], includePattern: ["^eng-"], excludePattern: ["-archive$"], maxChannels: 10 },
        gate: { minHumanEvents: 2, forceRunEveryNSkips: 4 },
        limits: { maxEvents: 500, maxActiveThreads: 100, maxRunsPerHour: 6 },
        cursor: { replicaSafetyMs: 15_000, overlapMs: 60_000, maxCatchupWindows: 3 },
      }),
    ).toEqual({ ok: true });
  });
});

describe("validateAwakeningConfig — rejects with a reason", () => {
  it("a non-object block", () => {
    expect(ok("yes").error).toMatch(/awakening must be an object/);
    expect(ok([]).ok).toBe(false);
  });

  it("a period below the floor — a typo must not make an agent wake every second", () => {
    expect(ok({ periodMs: 1000 }).error).toMatch(/periodMs must be an integer between 300000 and 86400000/);
    expect(ok({ periodMs: 60_000 }).ok).toBe(false);
  });

  it("a period above a day", () => {
    expect(ok({ periodMs: 48 * 60 * 60_000 }).ok).toBe(false);
  });

  it("a non-integer period", () => {
    expect(ok({ periodMs: 1_800_000.5 }).ok).toBe(false);
    expect(ok({ periodMs: "30m" }).ok).toBe(false);
  });

  it("an unknown kind or writePolicy", () => {
    expect(ok({ kind: "sideways" }).error).toMatch(/kind must be one of/);
    expect(ok({ writePolicy: "destroy" }).error).toMatch(/writePolicy must be one of/);
  });

  it("a non-boolean enabled / shadow", () => {
    expect(ok({ enabled: "true" }).ok).toBe(false);
    expect(ok({ shadow: 1 }).ok).toBe(false);
  });

  it("an invalid regular expression", () => {
    expect(ok({ channels: { includePattern: ["([a-z"] } }).error).toMatch(/not a valid regular expression/);
  });

  it("a catastrophic-backtracking pattern shape", () => {
    expect(ok({ channels: { includePattern: ["(a+)+$"] } }).error).toMatch(/nested quantifier/);
    expect(ok({ channels: { excludePattern: ["(x*)*"] } }).ok).toBe(false);
  });

  it("an oversized or over-numerous pattern list", () => {
    expect(ok({ channels: { includePattern: ["a".repeat(201)] } }).error).toMatch(/too long/);
    expect(ok({ channels: { includePattern: Array.from({ length: 11 }, (_, i) => `p${i}`) } }).error).toMatch(
      /too many patterns/,
    );
  });

  it("a non-string-array channel list", () => {
    expect(ok({ channels: { include: [1, 2] } }).error).toMatch(/must be an array of strings/);
    expect(ok({ channels: "eng" }).ok).toBe(false);
  });

  it("out-of-range limits and gate values", () => {
    expect(ok({ limits: { maxRunsPerHour: 0 } }).ok).toBe(false);
    expect(ok({ limits: { maxRunsPerHour: 1000 } }).ok).toBe(false);
    expect(ok({ limits: { maxEvents: 1 } }).ok).toBe(false);
    expect(ok({ gate: { minHumanEvents: -1 } }).ok).toBe(false);
    expect(ok({ channels: { maxChannels: 500 } }).ok).toBe(false);
    expect(ok({ cursor: { maxCatchupWindows: 0 } }).ok).toBe(false);
  });

  it("a non-string workspaceId", () => {
    expect(ok({ workspaceId: 42 }).ok).toBe(false);
  });
});

