/**
 * The pipeline's LlmClient (HTTP client).
 *
 * The completion itself runs on xyne-claw, where LITELLM_API_KEY lives —
 * claw-auth holds no LLM credentials (same arrangement as sessionCurator.ts).
 * This side keeps everything that isn't the credential: prompt assembly, JSON
 * parsing, schema validation and the repair loop.
 *
 * The schema goes in the prompt and is validated here with retry rather than
 * relying on response_format, because glm-latest does not enforce it reliably —
 * a json_schema response format actively corrupts its output.
 */

import { CONFIG } from "../../config.js";
import { createLogger, createTraceId } from "../../logger.js";
import {
  formatErrors,
  validate,
  type JsonCompletionRequest,
  type LlmClient,
} from "./pipeline/index.js";

const logger = createLogger("entity-llm-client", createTraceId());

/** Matches the claw-side ENTITY_EXTRACTION_TIMEOUT_MS plus slack for retries. */
const CLAW_TIMEOUT_MS = Number(process.env["ENTITY_EXTRACTION_TIMEOUT_MS"] ?? 300_000) + 60_000;

/** Repair attempts after the first response, i.e. 4 calls total. */
const MAX_REPAIR_ATTEMPTS = 3;

interface ChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

/** One raw completion via claw's S2S endpoint. */
async function completeViaClaw(messages: ChatMessage[], purpose?: string): Promise<string> {
  if (!CONFIG.xyneClawS2sKey) {
    throw new Error("XYNE_CLAW_S2S_KEY not set — entity extraction cannot reach claw");
  }

  const url = `${CONFIG.xyneClawUrl.replace(/\/$/, "")}/internal/entity-llm/complete`;
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-s2s-key": CONFIG.xyneClawS2sKey },
    body: JSON.stringify({ messages, ...(purpose ? { purpose } : {}) }),
    signal: AbortSignal.timeout(CLAW_TIMEOUT_MS),
  });

  if (!res.ok) {
    const body = await res.text().catch(() => "");
    throw new Error(`claw entity-llm ${res.status}: ${body.slice(0, 500)}`);
  }

  const data = (await res.json()) as { success?: boolean; content?: unknown; error?: unknown };
  if (!data.success || typeof data.content !== "string") {
    throw new Error(`claw entity-llm returned no content: ${String(data.error ?? "unknown")}`);
  }
  return data.content;
}

export const entityLlm: LlmClient = {
  async completeJson<T>(req: JsonCompletionRequest<T>): Promise<T> {
    const messages: ChatMessage[] = [
      {
        role: "system",
        content:
          `${req.system}\n\nRespond with JSON only — no prose, no code fences — ` +
          `matching this JSON Schema:\n${JSON.stringify(req.schema)}`,
      },
      { role: "user", content: req.user },
    ];
    let lastError = "";

    for (let attempt = 0; attempt <= MAX_REPAIR_ATTEMPTS; attempt++) {
      const raw = await completeViaClaw(messages, req.purpose);
      const parsed = tryParseJson(raw);

      if (!parsed.ok) {
        lastError = `Response was not valid JSON: ${parsed.error}`;
      } else {
        const errors = validate(parsed.value, req.schema);
        if (errors.length === 0) return parsed.value as T;
        lastError = formatErrors(errors);
      }

      logger.warn("[entity-llm] response rejected, retrying", {
        purpose: req.purpose,
        attempt: attempt + 1,
        error: lastError.slice(0, 300),
      });
      messages.push({ role: "assistant", content: raw.slice(0, 4000) });
      messages.push({
        role: "user",
        content:
          `That response did not match the required schema:\n${lastError}\n\n` +
          `Return only valid JSON matching the schema. No prose, no code fences.`,
      });
    }

    throw new Error(
      `LLM failed to produce schema-valid output for "${req.schemaName}" ` +
        `after ${MAX_REPAIR_ATTEMPTS + 1} attempts. Last error: ${lastError}`,
    );
  },
};

/** Tolerates code fences and surrounding prose around the JSON. */
function tryParseJson(raw: string): { ok: true; value: unknown } | { ok: false; error: string } {
  const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "").trim();
  const attempt = (candidate: string) => {
    try {
      return { ok: true as const, value: JSON.parse(candidate) };
    } catch {
      return null;
    }
  };
  const direct = attempt(cleaned);
  if (direct) return direct;
  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");
  if (start !== -1 && end > start) {
    const sliced = attempt(cleaned.slice(start, end + 1));
    if (sliced) return sliced;
  }
  return { ok: false, error: cleaned.slice(0, 200) || "(empty response)" };
}

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const flowActionSrc = readFileSync(resolve(here, "./flow-action.ts"), "utf8");
const webhookSrc = readFileSync(resolve(here, "./webhook.ts"), "utf8");

// Regression pin for the 2026-08-19 "App backend error 409" incident: the
// plan-approval staleness guard (introduced in the 2026-08-18 sync) required
// priorCtx.pendingPlan — a field Turn-1 NEVER writes for a non-trivial plan
// (webhook.ts /result stores only { ...ctx, planMessageId }; pendingPlan is
// first written when Turn 2 is dispatched). Every Approve/Reject click on a
// proposed plan card therefore 409'd as "stale or missing server plan".
//
// The guard was subsequently rebuilt on the durable AgentWidgetBinding row so a
// plan stays approvable after the 24h Redis TTL. That moved WHICH server record
// pins the card, so the assertions below track the records that exist now —
// the incident itself is still pinned by the first test.

describe("plan-approval staleness guard", () => {
  const guard = flowActionSrc.slice(
    flowActionSrc.indexOf("A plan action must target the exact outstanding server-created card"),
    flowActionSrc.indexOf("const planAgentSlug"),
  );

  it("does not require ctx.pendingPlan, which Turn-1 never writes", () => {
    expect(guard).not.toContain("priorCtx.pendingPlan");
  });

  it("still pins the exact card on the server's own records", () => {
    // Anti-substitution: a click whose messageId doesn't match the live
    // active-card record is a superseded card and must be refused.
    expect(guard).toContain("activePlan.messageId !== messageId");
    // The durable row is the authority on liveness — superseded / already
    // approved / already rejected can never be re-actioned.
    expect(guard).toContain('planBinding.status !== "proposed"');
    // And the todos the dispatch trusts must actually exist on a server record.
    expect(guard).toContain("activePlan?.todos?.length");
    expect(guard).toContain("bindingData");
  });

  it("does NOT gate on the 24h session, so a plan stays approvable for days", () => {
    // The SessionContext (and its planMessageId) expires with Redis while the
    // card in the thread does not. Requiring either here is what made an old
    // but perfectly valid plan card un-approvable — the durable binding carries
    // the routing and the plan owner instead. Re-adding either of these
    // re-breaks approval after 24h.
    expect(guard).not.toContain("priorCtx.planMessageId !== messageId");
    expect(guard).not.toContain("!priorCtx ||");
  });

  it("matches Turn-1's actual writes: planMessageId-only session AND a durable binding", () => {
    // If someone later makes Turn-1 persist pendingPlan, this documents the
    // current contract they're changing: the proposed-plan /result write is
    // planMessageId-only.
    expect(webhookSrc).toContain("await setSession(sessionId, { ...ctx, planMessageId }).catch(() => {});");
    // Durability rests entirely on this write — without it the guard silently
    // degrades back to Redis-only, 24h-lifetime approval.
    expect(webhookSrc).toContain("await upsertPlanBinding({");
  });
});

import type { Session } from '@xyne/kata-sdk';
